import { defineCollection } from 'astro:content';
import { docsLoader, i18nLoader } from '@astrojs/starlight/loaders';
import { docsSchema, i18nSchema } from '@astrojs/starlight/schema';
import { docsVersionsLoader } from 'starlight-versions/loader';

// src/content/docs is generated by `npm run sync-docs` (the docs/ tree of each
// version of ../versions.mjs plus src/content/overlay) and is gitignored; the
// default docsLoader reads it. The `versions` collection holds the sidebar of
// each version under a slug, read by the starlight-versions plugin
// (src/content/versions/*.json, generated and gitignored too).
//
// The `i18n` collection (src/content/i18n/*.json, committed) overrides Starlight
// UI strings: here, the wording of the search notice of starlight-versions on
// the pages of a version, which points to the latest release at the site root.
export const collections = {
	docs: defineCollection({ loader: docsLoader(), schema: docsSchema() }),
	versions: defineCollection({ loader: docsVersionsLoader() }),
	i18n: defineCollection({ loader: i18nLoader(), schema: i18nSchema() }),
};
